splay:table-header-group;\">\n    <tr>\n      <th width=\"{{ w.loc }}%\" style=\"width:{{ w.loc }}%;white-space:nowrap;padding:4px;\">LOCATION</th><th width=\"{{ w.code }}%\" style=\"width:{{ w.code }}%;white-space:nowrap;padding:4px;\">ITEM CODE</th>\n      <th width=\"{{ w.qty }}%\" style=\"width:{{ w.qty }}%;white-space:nowrap;padding:4px;\">QTY</th>{% if cols.qty %}<th width=\"{{ w.new_qty }}%\" style=\"width:{{ w.new_qty }}%;white-space:nowrap;padding:4px;\">NEW QTY</th>{% endif %}\n      <th width=\"{{ w.dd }}%\" style=\"width:{{ w.dd }}%;white-space:nowrap;padding:4px;\">DELIVERY</th>{% if cols.delivery_date %}<th width=\"{{ w.new_dd }}%\" style=\"width:{{ w.new_dd }}%;white-space:nowrap;padding:4px;\">NEW DATE</th>{% endif %}\n      <th width=\"{{ w.remark }}%\" style=\"width:{{ w.remark }}%;white-space:nowrap;padding:4px;\">REMARK</th>\n    </tr>\n  </thead>\n  <tbody>\n    {% for line in handover.lines %}\n    {% if grouped and (loop.first or line.so_number != loop.previtem.so_number) %}\n    <tr style=\"page-break-inside:avoid;\"><td colspan=\"{{ span }}\" style=\"white-space:nowrap;padding:4px;background-color:#f3f4f6;font-weight:600;\">S/O NO {{ line.so_number | default(\"\", true) }}</td></tr>\n    {% endif %}\n    <tr style=\"page-break-inside:avoid;\">\n      <td style=\"white-space:nowrap;padding:4px;\">{{ line.location | default(\"\", true) }}</td>\n      <td style=\"white-space:nowrap;padding:4px;\">{{ line.item_code | default(\"\", true) }}</td>\n      <td style=\"white-space:nowrap;padding:4px;\">{% if line.was and line.was.qty %}{{ line.was.qty }}{% else %}{{ line.qty | default(\"\", true) }}{% endif %}</td>\n      {% if cols.qty %}<td style=\"white-space:nowrap;padding:4px;\">{% if line.was and line.was.qty %}{{ line.qty | default(\"\", true) }}{% endif %}</td>{% endif %}\n      <td style=\"white-space:nowrap;padding:4px;\">{% if line.was and line.was.delivery_date %}{{ line.was.delivery_date }}{% else %}{{ line.delivery_date | default(\"\", t